import assert from 'node:assert/strict';
import test from 'node:test';
import { merge } from '../src/accounts/merge.js';

const store = accounts => ({ get: id => accounts[id] });

test('a support lead can merge', () => {
  const accounts = { a: { orders: [1], disputes: [] }, b: { orders: [2], disputes: [] } };
  merge(store(accounts), 'a', 'b', { roles: ['support-lead'] });
  assert.deepEqual(accounts.a.orders, [1, 2]);
});

// AC-3 (R-3): Given an account with an open dispute, when a support lead
// merges it, then the merge is refused and nothing moves.
const lead = { roles: ['support-lead'] };

const account = (id, disputes = []) => ({
  orders: [`${id}-order`],
  addresses: [`${id}-address`],
  notes: [`${id}-note`],
  disputes,
});

const assertNothingMoved = (accounts, before) => {
  assert.deepEqual(accounts, before);
  assert.notEqual(accounts.b.closed, true);
  assert.equal(accounts.b.mergedInto, undefined);
};

test('AC-3: merge is refused when the newer account has an open dispute, and nothing moves', () => {
  const accounts = { a: account('a'), b: account('b', [{ id: 'd1', status: 'open' }]) };
  const before = structuredClone(accounts);
  assert.throws(() => merge(store(accounts), 'a', 'b', lead));
  assertNothingMoved(accounts, before);
});

test('AC-3: merge is refused when the older account has an open dispute, and nothing moves', () => {
  const accounts = { a: account('a', [{ id: 'd1', status: 'open' }]), b: account('b') };
  const before = structuredClone(accounts);
  assert.throws(() => merge(store(accounts), 'a', 'b', lead));
  assertNothingMoved(accounts, before);
});

test('AC-3: one open dispute among resolved ones still blocks the merge', () => {
  const accounts = {
    a: account('a'),
    b: account('b', [{ id: 'd1', status: 'resolved' }, { id: 'd2', status: 'open' }]),
  };
  const before = structuredClone(accounts);
  assert.throws(() => merge(store(accounts), 'a', 'b', lead));
  assertNothingMoved(accounts, before);
});

test('AC-3: a resolved (not open) dispute does not block the merge', () => {
  const accounts = { a: account('a'), b: account('b', [{ id: 'd1', status: 'resolved' }]) };
  merge(store(accounts), 'a', 'b', lead);
  assert.deepEqual(accounts.a.orders, ['a-order', 'b-order']);
  assert.equal(accounts.b.closed, true);
  assert.equal(accounts.b.mergedInto, 'a');
});
